-- Execute in a new Supabase project SQL editor. Review policies before production use.
create extension if not exists pgcrypto;
create type public.user_role as enum ('author','specialist','manager','admin');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.user_role not null default 'author',created_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id),title text not null,genre text,description text,service text not null,status text not null default 'submitted',stage text not null default 'assessment',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.project_files (id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,uploaded_by uuid not null references public.profiles(id),file_name text not null,storage_path text not null unique,size_bytes bigint not null,created_at timestamptz not null default now());
create table public.approvals (id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,label text not null,status text not null default 'pending',approved_by uuid references public.profiles(id),approved_at timestamptz,created_at timestamptz not null default now());
create table public.invoices (id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id),project_id uuid references public.projects(id),description text,amount_cents integer not null check(amount_cents>0),currency text not null default 'USD' check(currency='USD'),status text not null default 'pending' check(status in ('pending','paid','void','refunded')),created_at timestamptz not null default now(),paid_at timestamptz);
create table public.payment_attempts (id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id),reference text not null unique,amount_cents integer not null,currency text not null,status text not null default 'initialized',provider_id text,created_at timestamptz not null default now());
create table public.distribution_records (id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,platform text not null,status text not null default 'not_submitted',retailer_url text,external_identifier text,updated_at timestamptz not null default now());
create table public.books (id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id),title text not null,author_name text not null,description text,cover_url text,retailer_links jsonb not null default '{}'::jsonb,is_public boolean not null default false,created_at timestamptz not null default now());
create table public.audit_log (id bigint generated always as identity primary key,actor_id uuid,action text not null,resource_type text not null,resource_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create function public.create_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name');return new;end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_profile();
create function public.is_staff() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=(select auth.uid()) and role in ('manager','admin'))$$;
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin')$$;
create function public.owns_project(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.projects where id=pid and author_id=(select auth.uid()))$$;
alter table public.profiles enable row level security;alter table public.projects enable row level security;alter table public.project_files enable row level security;alter table public.approvals enable row level security;alter table public.invoices enable row level security;alter table public.payment_attempts enable row level security;alter table public.distribution_records enable row level security;alter table public.books enable row level security;alter table public.audit_log enable row level security;
create policy "profile read" on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_staff());
create policy "project read" on public.projects for select to authenticated using(author_id=(select auth.uid()) or public.is_staff());
create policy "project author insert" on public.projects for insert to authenticated with check(author_id=(select auth.uid()));
create policy "project staff update" on public.projects for update to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "file read" on public.project_files for select to authenticated using(public.owns_project(project_id) or public.is_staff());
create policy "file insert" on public.project_files for insert to authenticated with check(uploaded_by=(select auth.uid()) and (public.owns_project(project_id) or public.is_staff()));
create policy "approval read" on public.approvals for select to authenticated using(public.owns_project(project_id) or public.is_staff());
create policy "approval author update" on public.approvals for update to authenticated using(public.owns_project(project_id) and status='pending') with check(public.owns_project(project_id) and status='approved' and approved_by=(select auth.uid()));
create policy "invoice read" on public.invoices for select to authenticated using(author_id=(select auth.uid()) or public.is_staff());
create policy "distribution read" on public.distribution_records for select to authenticated using(public.owns_project(project_id) or public.is_staff());
create policy "public books" on public.books for select to anon,authenticated using(is_public=true or public.is_staff() or public.owns_project(project_id));
-- Payment attempts are never writable by browser clients. Create server-side with service role only.
-- Private storage bucket with path starting with authenticated user's ID.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('manuscripts','manuscripts',false,20971520,null) on conflict(id) do nothing;
create policy "author storage upload" on storage.objects for insert to authenticated with check(bucket_id='manuscripts' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "author storage read" on storage.objects for select to authenticated using(bucket_id='manuscripts' and ((storage.foldername(name))[1]=(select auth.uid())::text or public.is_staff()));
-- Only service role can invoke settlement. All invoice changes are atomic and idempotent.
create function public.settle_verified_payment(p_reference text,p_provider_id text) returns void language plpgsql security definer set search_path='' as $$declare a public.payment_attempts%rowtype;begin select * into a from public.payment_attempts where reference=p_reference for update;if not found then raise exception 'Unknown payment';end if;if a.status='paid' then return;end if;update public.payment_attempts set status='paid',provider_id=p_provider_id where id=a.id;update public.invoices set status='paid',paid_at=now() where id=a.invoice_id and status='pending';insert into public.audit_log(action,resource_type,resource_id,details) values('payment_verified','invoice',a.invoice_id::text,jsonb_build_object('reference',p_reference));end $$;
revoke all on function public.settle_verified_payment(text,text) from public,anon,authenticated;
grant execute on function public.settle_verified_payment(text,text) to service_role;
